import { writeFile } from 'fs/promises'

// Smallest valid 1x1 white JPEG, used as a base to write real EXIF tags into.
export const MINIMAL_JPEG_BASE64 =
  ''

export async function writeMinimalJpeg(path: string): Promise<void> {
  await writeFile(path, Buffer.from(MINIMAL_JPEG_BASE64, 'base64'))
}
